static void ublk_queue_reset_io_flags(struct ublk_queue *ubq)
{
	int j;

	/* UBLK_IO_FLAG_CANCELED can be cleared now */
	spin_lock(&ubq->cancel_lock);
	for (j = 0; j < ubq->q_depth; j++)
